/**
 * Validates and sanitizes WizzTech platform verification API endpoint.
 *
 * The SDK is environment-agnostic and does not read host environment variables directly.
 * Host applications must pass their platform URL into WizzTechProtectionProvider via the `platformUrl` prop.
 *
 * Example:
 * <WizzTechProtectionProvider platformUrl={import.meta.env.VITE_WIZZTECH_PLATFORM_URL}>
 *   <App />
 * </WizzTechProtectionProvider>
 */
export declare function getPlatformUrl(platformUrl?: string): string;
